public class SseHub {
  private final CopyOnWriteArrayList<SseEmitter> emitters = new CopyOnWriteArrayList<>();
  private final ObjectMapper mapper = new ObjectMapper();
  public SseEmitter subscribe() {
    SseEmitter emitter = new SseEmitter(300_000L);
    emitters.add(emitter);
    emitter.onCompletion(() -> emitters.remove(emitter));
    emitter.onTimeout(() -> emitters.remove(emitter));
    emitter.onError(e -> emitters.remove(emitter));
    send(emitter, "connected", Map.of("message","Stock updates connected."));
    return emitter;
  }
  public void broadcast(List<StockEvent> events) {
    if (events.isEmpty()) return;
    for (SseEmitter e : emitters) {
      try { e.send(SseEmitter.event().name("stock").data(mapper.writeValueAsString(events))); }
      catch(Exception ex) { emitters.remove(e); }
    }
  }
  @Scheduled(fixedDelay=20000)
  public void heartbeat() { for (...) try { e.send(SseEmitter.event().comment("ping")); } catch ... }
