        for (int i = 6; i >= 0; i--) {
            String date = today.minusDays(i).toString();
            long[] values = byDay.getOrDefault(date, new long[]{0L, 0L});
            trend.add(new DashboardView.TrendPoint(date, values[0], values[1]));
