            throw new ApiException(ErrorCode.NOT_FOUND, "Image not found.");
        }
        try {
            return Files.readAllBytes(path);
        } catch (IOException e) {
            throw new ApiException(ErrorCode.NOT_FOUND, "Image not found.");
        }
    }

    public String mediaType(String name) {
        if (name.endsWith(".png")) return "image/png";
        if (name.endsWith(".webp")) return "image/webp";
        return "image/jpeg";
    }
}
