        OrderRules.Resolved r = OrderRules.resolve(TODAY, LocalTime.of(16, 0), tomorrow, "Dinner");
        assertEquals(tomorrow, r.deliveryDate());
        assertEquals("Dinner", r.mealPeriod());
        assertEquals("", r.notice());
