        ? f.categories.filter((c) => c !== category)
        : [...f.categories, category],
    }))
  }

  return (
    <>
      <div className="page-head">
        <div>
          <h1>Today's Menu</h1>
          <p className="muted">{menu.menuDate} · {menu.totalElements} dishes available</p>
