.link-btn { background: none; border: 0; color: var(--primary); font-weight: 600; padding: .75rem 0; display: block; margin: 0 auto; }

/* ---------- top navigation ---------- */
.topbar { background: var(--surface); border-bottom: 1px solid var(--border); position: sticky; top: 0; z-index: 30; }
.topbar-inner { max-width: 1240px; margin: 0 auto; padding: .7rem 1.5rem; display: flex; align-items: center; gap: 1.5rem; }
.brand { display: flex; align-items: center; gap: .6rem; background: none; border: 0; font-weight: 800; font-size: 1.05rem; padding: 0; }
.brand small { display: block; font-size: .68rem; font-weight: 500; color: var(--muted); letter-spacing: .04em; text-transform: uppercase; }
.brand-mark { width: 34px; height: 34px; border-radius: 10px; background: var(--primary); color: #fff; display: grid; place-items: center; font-weight: 800; }
.brand.big { font-size: 1.6rem; margin-bottom: 2rem; }
.brand.big .brand-mark { width: 44px; height: 44px; font-size: 1.3rem; }
.main-nav { display: flex; gap: .25rem; flex: 1; }
.nav-link { background: none; border: 0; padding: .55rem .85rem; border-radius: 9px; font-weight: 600; font-size: .9rem; color: var(--muted); }
.nav-link:hover { background: var(--surface-soft); color: var(--text); }
.nav-link.active { background: var(--primary-soft); color: var(--primary-dark); }
.nav-icon { margin-right: .35rem; }
.user-box { display: flex; align-items: center; gap: .6rem; }
.user-name { font-size: .86rem; font-weight: 600; }
.role-chip { background: var(--accent-soft); color: var(--accent); font-size: .72rem; font-weight: 700; padding: .2rem .5rem; border-radius: 20px; text-transform: uppercase; letter-spacing: .04em; }

/* ---------- auth ---------- */
.auth-page { min-height: 100vh; display: grid; grid-template-columns: 1.1fr 1fr; }
.auth-hero { background: linear-gradient(145deg, #0d6e4f, #0a4c39 60%, #114b3d); color: #fff; padding: 4rem 3.5rem; display: flex; flex-direction: column; justify-content: center; }
.auth-hero .brand-mark { background: rgba(255,255,255,.18); }
.auth-hero h1 { font-size: 2.6rem; max-width: 15ch; margin-bottom: 1rem; }
.auth-hero p { color: rgba(255,255,255,.82); max-width: 42ch; font-size: 1.05rem; }
.auth-hero ul { margin: 1.5rem 0 0; padding-left: 1.2rem; color: rgba(255,255,255,.85); line-height: 2; }
.auth-card { background: var(--surface); display: flex; flex-direction: column; justify-content: center; padding: 3rem clamp(1.5rem, 6vw, 5rem); }
.auth-card form { max-width: 380px; width: 100%; }
.field { display: block; margin-bottom: 1rem; }
.field > span { display: block; font-size: .85rem; font-weight: 600; margin-bottom: .35rem; }
.field input, .field select, .field textarea, .toolbar input, .toolbar select,
.search-wrap input, .ai-input input, .inline-field input {
  width: 100%; border: 1px solid var(--border); background: var(--surface);
  border-radius: 9px; padding: .6rem .75rem; outline: none;
}
.field input:focus, .field select:focus, .field textarea:focus,
.search-wrap input:focus, .ai-input input:focus, .toolbar input:focus {
  border-color: var(--primary); box-shadow: 0 0 0 3px var(--primary-soft);
}
.field textarea { resize: vertical; }
.form-error { background: var(--danger-soft); color: var(--danger); padding: .6rem .75rem; border-radius: 9px; font-size: .88rem; margin-bottom: .8rem; }
.form-hint { color: var(--muted); font-size: .82rem; margin: .35rem 0 1rem; }
.demo-hint { margin-top: 1.5rem; padding: .9rem; background: var(--surface-soft); border-radius: 10px; font-size: .8rem; color: var(--muted); line-height: 1.7; }
.demo-hint strong { color: var(--text); display: block; margin-bottom: .25rem; }

/* ---------- page head, filters ---------- */
.page-head { display: flex; align-items: flex-end; justify-content: space-between; gap: 1rem; margin-bottom: 1.25rem; flex-wrap: wrap; }
.page-head p { margin: 0; }
.notice { background: var(--primary-soft); color: var(--primary-dark); border: 1px solid #c9e5d7; padding: .7rem 1rem; border-radius: 10px; margin-bottom: 1rem; font-size: .9rem; }
.notice.warn { background: var(--warn-soft); color: var(--warn); border-color: #f2dfae; }
.filter-bar { background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius); padding: 1rem; margin-bottom: 1.25rem; display: flex; flex-direction: column; gap: .8rem; }
.search-wrap { position: relative; max-width: 420px; width: 100%; }
.search-wrap input { padding-left: 2.2rem; }
.search-icon { position: absolute; left: .7rem; top: 50%; transform: translateY(-50%); color: var(--muted); font-size: 1.2rem; }
.chip-row { display: flex; flex-wrap: wrap; gap: .4rem; }
.chip { border: 1px solid var(--border); background: var(--surface); color: var(--muted); border-radius: 20px; padding: .35rem .8rem; font-size: .82rem; font-weight: 600; }
.chip:hover { border-color: var(--primary); color: var(--primary); }
.chip.selected { background: var(--primary); border-color: var(--primary); color: #fff; }
.chip.selected.danger { background: var(--danger); border-color: var(--danger); }
.chip.clear { background: transparent; border-style: dashed; }
.switch { display: inline-flex; align-items: center; gap: .5rem; font-size: .9rem; font-weight: 600; cursor: pointer; }
.switch input { width: 18px; height: 18px; accent-color: var(--primary); }
.switch.inline { margin-top: 1.4rem; }

/* ---------- dish cards ---------- */
.dish-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(245px, 1fr)); gap: 1rem; }
.dish-card { background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius); overflow: hidden; box-shadow: 0 2px 8px rgba(18,45,34,.04); display: flex; flex-direction: column; transition: transform .15s, box-shadow .15s; }
.dish-card:hover { transform: translateY(-2px); box-shadow: var(--shadow); }
.dish-card.is-recommended { border-color: #b9a6ff; box-shadow: 0 0 0 2px var(--accent-soft); }
.dish-card.is-soldout { opacity: .72; }
.dish-media { position: relative; border: 0; padding: 0; background: linear-gradient(135deg, #dfeae4, #cfe0d6); height: 150px; overflow: hidden; display: block; }
.dish-media img { width: 100%; height: 100%; object-fit: cover; }
.sold-out-veil { position: absolute; inset: 0; background: rgba(20,32,26,.55); color: #fff; display: grid; place-items: center; font-weight: 700; letter-spacing: .08em; text-transform: uppercase; }
.recommend-flag { position: absolute; top: .55rem; left: .55rem; background: var(--accent); color: #fff; font-size: .72rem; font-weight: 700; padding: .25rem .55rem; border-radius: 20px; }
.dish-body { padding: .85rem; display: flex; flex-direction: column; flex: 1; }
.dish-tags { display: flex; gap: .35rem; margin-bottom: .5rem; }
.tag { background: var(--primary-soft); color: var(--primary-dark); font-size: .72rem; font-weight: 700; padding: .18rem .5rem; border-radius: 6px; }
.tag.subtle { background: var(--surface-soft); color: var(--muted); }
.tag.spice { background: var(--danger-soft); color: var(--danger); }
.dish-name { font-size: 1rem; cursor: pointer; margin-bottom: .3rem; }
.dish-name:hover { color: var(--primary); }
.dish-desc { color: var(--muted); font-size: .8rem; line-height: 1.45; margin-bottom: .7rem; flex: 1; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }
.dish-meta { display: flex; align-items: center; justify-content: space-between; margin-bottom: .7rem; }
.dish-price { font-weight: 800; font-size: 1.05rem; color: var(--text); }
.stock-badge { font-size: .72rem; color: var(--muted); background: var(--surface-soft); padding: .2rem .5rem; border-radius: 6px; }
.stock-badge.low { background: var(--warn-soft); color: var(--warn); font-weight: 700; }
.stock-badge.out { background: var(--danger-soft); color: var(--danger); font-weight: 700; }
.dish-actions { display: flex; gap: .4rem; }
.dish-actions .btn { flex: 1; }
.pager { display: flex; align-items: center; justify-content: center; gap: 1rem; margin-top: 1.5rem; color: var(--muted); font-size: .88rem; }
.sticky-hint { position: fixed; bottom: 1rem; left: 50%; transform: translateX(-50%); background: var(--warn-soft); color: var(--warn); border: 1px solid #f0dcae; padding: .6rem 1rem; border-radius: 30px; font-size: .85rem; font-weight: 600; box-shadow: var(--shadow); z-index: 20; }

/* ---------- panels, tables ---------- */
.panel { background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius); padding: 1.15rem; margin-bottom: 1.2rem; }
.two-col { display: grid; grid-template-columns: 1fr 1fr; gap: 1.2rem; }
.three-col { display: grid; grid-template-columns: repeat(3, 1fr); gap: .8rem; }
.data-table { width: 100%; border-collapse: collapse; font-size: .87rem; }
.data-table th { text-align: left; color: var(--muted); font-size: .76rem; text-transform: uppercase; letter-spacing: .05em; padding: .6rem .5rem; border-bottom: 1px solid var(--border); }
.data-table td { padding: .65rem .5rem; border-bottom: 1px solid var(--border); vertical-align: middle; }
.data-table tr:last-child td { border-bottom: 0; }
.table-panel { overflow-x: auto; }
.table-thumb { width: 44px; height: 36px; object-fit: cover; border-radius: 6px; }
.cell-sub { color: var(--muted); font-size: .76rem; max-width: 240px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.status { font-size: .74rem; font-weight: 700; padding: .22rem .55rem; border-radius: 20px; background: var(--surface-soft); color: var(--muted); }
.status.pending { background: var(--warn-soft); color: var(--warn); }
.status.confirmed { background: var(--primary-soft); color: var(--primary-dark); }
.status.completed { background: #e8f0ff; color: #2f5bb7; }
.status.cancelled { background: var(--danger-soft); color: var(--danger); }
.toolbar { display: flex; gap: .6rem; align-items: center; flex-wrap: wrap; margin-bottom: 1rem; }
.toolbar input[type=search] { max-width: 260px; }
.toolbar select, .inline-field input { width: auto; }
.inline-field { display: flex; align-items: center; gap: .5rem; font-weight: 600; font-size: .87rem; }
.qty-input { width: 90px; border: 1px solid var(--border); border-radius: 8px; padding: .35rem .5rem; }

/* ---------- modal ---------- */
.modal-backdrop { position: fixed; inset: 0; background: rgba(14, 30, 23, .48); display: grid; place-items: center; padding: 1rem; z-index: 60; }
.modal { background: var(--surface); border-radius: 16px; width: min(520px, 100%); max-height: 90vh; display: flex; flex-direction: column; box-shadow: 0 24px 60px rgba(10,30,20,.25); }
.modal-wide { width: min(820px, 100%); }
.modal-head { display: flex; align-items: center; justify-content: space-between; padding: 1rem 1.25rem; border-bottom: 1px solid var(--border); }
.modal-head h2 { margin: 0; }
.modal-body { padding: 1.25rem; overflow-y: auto; }
.modal-foot { padding: .9rem 1.25rem; border-top: 1px solid var(--border); display: flex; justify-content: flex-end; gap: .5rem; }
.detail-grid { display: grid; grid-template-columns: 210px 1fr; gap: 1.1rem; margin-bottom: 1.2rem; }
.detail-image { width: 210px; height: 170px; object-fit: cover; border-radius: 12px; background: var(--surface-soft); }
.detail-description { color: var(--muted); font-size: .9rem; }
.detail-facts { display: grid; grid-template-columns: 1fr 1fr; gap: .6rem 1rem; margin: 0; }
.detail-facts div { background: var(--surface-soft); border-radius: 9px; padding: .5rem .7rem; }
.detail-facts dt { font-size: .72rem; color: var(--muted); text-transform: uppercase; letter-spacing: .04em; }
.detail-facts dd { margin: .15rem 0 0; font-weight: 600; font-size: .88rem; }
.inline-warning { margin-top: .8rem; background: var(--warn-soft); color: var(--warn); padding: .6rem .75rem; border-radius: 9px; font-size: .84rem; }
.option-group { border-top: 1px solid var(--border); padding-top: 1rem; margin-top: 1rem; }
.option-group-head { display: flex; align-items: baseline; justify-content: space-between; margin-bottom: .6rem; }
.option-list { display: flex; flex-wrap: wrap; gap: .45rem; }
.option-item { display: flex; align-items: center; gap: .4rem; border: 1px solid var(--border); border-radius: 9px; padding: .4rem .65rem; font-size: .86rem; cursor: pointer; }
.option-item.checked { border-color: var(--primary); background: var(--primary-soft); color: var(--primary-dark); font-weight: 600; }
.option-item input { accent-color: var(--primary); }
.option-extra { color: var(--muted); font-size: .78rem; }
.detail-footer { width: 100%; display: flex; align-items: center; justify-content: space-between; }
.detail-price { font-size: 1.35rem; font-weight: 800; }
.allergen-confirm { margin-top: 1rem; background: var(--danger-soft); color: var(--danger); border-radius: 10px; padding: .9rem; }
.allergen-confirm .row { margin-top: .6rem; }

/* ---------- toasts / states ---------- */
.toast-wrap { position: fixed; top: 1rem; right: 1rem; display: flex; flex-direction: column; gap: .5rem; z-index: 100; max-width: min(360px, calc(100vw - 2rem)); }
.toast { background: var(--surface); border: 1px solid var(--border); border-left: 4px solid var(--primary); border-radius: 10px; padding: .7rem .8rem; box-shadow: var(--shadow); font-size: .88rem; display: flex; justify-content: space-between; gap: .5rem; cursor: pointer; }
.toast.success { border-left-color: var(--primary); }
.toast.warn { border-left-color: var(--warn); }
.toast.error { border-left-color: var(--danger); }
.toast-close { background: none; border: 0; color: var(--muted); font-size: 1.1rem; }
.loading { display: flex; align-items: center; justify-content: center; gap: .6rem; color: var(--muted); padding: 2.5rem 1rem; }
.spinner { width: 18px; height: 18px; border: 2px solid var(--border); border-top-color: var(--primary); border-radius: 50%; animation: spin .8s linear infinite; }
@keyframes spin { to { transform: rotate(360deg); } }
.empty { text-align: center; padding: 3rem 1rem; color: var(--muted); }
.empty-icon { font-size: 2rem; opacity: .4; }
.empty h3 { color: var(--text); }

/* ---------- AI drawer ---------- */
.drawer-backdrop { position: fixed; inset: 0; background: rgba(14,30,23,.4); z-index: 50; display: flex; justify-content: flex-end; }
.drawer { background: var(--surface); width: min(460px, 100%); height: 100%; display: flex; flex-direction: column; box-shadow: -12px 0 40px rgba(10,30,20,.2); }
.drawer-head { padding: 1rem 1.25rem; border-bottom: 1px solid var(--border); display: flex; justify-content: space-between; align-items: flex-start; }
.drawer-head h2 { margin: 0; }
.drawer-body { padding: 1.25rem; overflow-y: auto; flex: 1; }
.ai-input { display: flex; gap: .5rem; }
.ai-input input { flex: 1; }
.ai-suggestions { display: flex; flex-wrap: wrap; gap: .35rem; margin: .7rem 0; }
.ai-suggestions .chip { font-size: .74rem; }
.ai-status { background: var(--accent-soft); color: var(--accent); border-radius: 9px; padding: .6rem .75rem; font-size: .84rem; margin-bottom: .8rem; }
.ai-thinking { white-space: pre-wrap; word-break: break-word; background: var(--surface-soft); border-radius: 9px; padding: .7rem; font-size: .78rem; color: var(--muted); max-height: 150px; overflow-y: auto; font-family: inherit; }
.ai-results { display: flex; flex-direction: column; gap: .8rem; margin-top: 1rem; }
.ai-card { display: grid; grid-template-columns: 76px 1fr; gap: .75rem; border: 1px solid var(--border); border-radius: 12px; padding: .6rem; }
.ai-card img { width: 76px; height: 76px; object-fit: cover; border-radius: 8px; }
.ai-reason { font-size: .82rem; color: var(--muted); margin: .35rem 0; }

/* ---------- cart / checkout / orders ---------- */
.cart-line { display: grid; grid-template-columns: 66px 1fr auto auto; gap: .9rem; align-items: center; padding: .8rem 0; border-bottom: 1px solid var(--border); }
.cart-line:last-child { border-bottom: 0; }
.cart-line img { width: 66px; height: 56px; object-fit: cover; border-radius: 8px; }
.cart-options { font-size: .78rem; color: var(--muted); }
.qty-control { display: flex; align-items: center; border: 1px solid var(--border); border-radius: 9px; overflow: hidden; }
.qty-control button { background: var(--surface-soft); border: 0; width: 30px; height: 30px; font-size: 1rem; }
.qty-control button:disabled { opacity: .4; cursor: not-allowed; }
.qty-control span { min-width: 30px; text-align: center; font-weight: 700; }
.line-total { min-width: 76px; text-align: right; }
.checkout-summary { display: flex; align-items: center; justify-content: space-between; background: var(--surface); border: 1px solid var(--border); border-radius: var(--radius); padding: 1.1rem 1.25rem; }
.grand-total { font-size: 1.6rem; font-weight: 800; }
.summary-line { display: flex; justify-content: space-between; padding: .55rem 0; border-bottom: 1px solid var(--border); font-size: .9rem; }
.summary-total { display: flex; justify-content: space-between; align-items: center; padding-top: .9rem; font-size: 1.15rem; }
.segmented { display: flex; border: 1px solid var(--border); border-radius: 9px; overflow: hidden; }
.segmented button { flex: 1; border: 0; background: var(--surface); padding: .55rem; font-weight: 600; }
.segmented button.selected { background: var(--primary); color: #fff; }
.success-card { max-width: 620px; margin: 2rem auto; background: var(--surface); border: 1px solid var(--border); border-radius: 18px; padding: 2rem; text-align: center; box-shadow: var(--shadow); }
.success-icon { width: 60px; height: 60px; border-radius: 50%; background: var(--primary-soft); color: var(--primary); font-size: 2rem; display: grid; place-items: center; margin: 0 auto 1rem; }
.success-order { display: grid; grid-template-columns: 1fr 1fr; gap: .8rem; text-align: left; margin: 1.5rem 0; }
.success-order div { background: var(--surface-soft); border-radius: 10px; padding: .65rem .8rem; }
.success-order span { display: block; font-size: .75rem; }
.success-order strong { font-size: .95rem; }
.order-row { display: grid; grid-template-columns: 1.4fr 1.2fr .8fr .6fr auto; gap: .8rem; align-items: center; padding: .8rem .3rem; border-bottom: 1px solid var(--border); font-size: .88rem; }
.order-row:last-child { border-bottom: 0; }
.pref-panel section { padding-bottom: 1.1rem; margin-bottom: 1.1rem; border-bottom: 1px solid var(--border); }
.pref-panel section:last-of-type { border-bottom: 0; }

/* ---------- console ---------- */
.console-main { max-width: none; padding: 0; }
.console-shell { display: grid; grid-template-columns: 230px 1fr; min-height: 100vh; }
.console-sidebar { background: #10271f; color: #fff; padding: 1.4rem 1rem; display: flex; flex-direction: column; }
.console-brand { display: flex; align-items: center; gap: .6rem; padding: 0 .4rem 1.5rem; border-bottom: 1px solid rgba(255,255,255,.12); }
.console-brand .brand-mark { background: #2f9c73; }
.console-brand small { display: block; color: rgba(255,255,255,.6); font-size: .72rem; }
.console-nav { display: flex; flex-direction: column; gap: .3rem; margin-top: 1.5rem; }
.console-nav button { background: none; border: 0; color: rgba(255,255,255,.72); text-align: left; padding: .7rem .8rem; border-radius: 9px; font-weight: 600; display: flex; gap: .6rem; align-items: center; }
.console-nav button:hover { background: rgba(255,255,255,.08); color: #fff; }
.console-nav button.active { background: #2f9c73; color: #fff; }
.console-sidebar-foot { margin-top: auto; font-size: .76rem; }
.console-sidebar-foot .btn { background: rgba(255,255,255,.1); color: #fff; border-color: rgba(255,255,255,.2); }
.console-content { padding: 1.6rem clamp(1rem, 3vw, 2.2rem) 3rem; background: var(--bg); min-width: 0; }
.console-head { display: flex; justify-content: space-between; align-items: flex-start; margin-bottom: 1.4rem; }
.console-head p { margin: 0; }
.upload-preview { display: flex; align-items: center; gap: .6rem; font-size: .75rem; }
.upload-preview img { width: 60px; height: 50px; object-fit: cover; border-radius: 8px; }
.option-editor { margin-top: 1.2rem; border-top: 1px solid var(--border); padding-top: 1rem; }
.group-editor { background: var(--surface-soft); border-radius: 10px; padding: .8rem; margin-top: .7rem; }
.group-editor .row input { border: 1px solid var(--border); border-radius: 8px; padding: .4rem .6rem; flex: 1; min-width: 90px; }
.metric-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(150px, 1fr)); gap: .8rem; margin-bottom: 1.2rem; }
.metric { background: var(--surface); border: 1px solid var(--border); border-radius: 12px; padding: .9rem 1rem; }
.metric.accent { background: var(--primary); border-color: var(--primary); color: #fff; }
.metric-label { display: block; font-size: .76rem; color: var(--muted); text-transform: uppercase; letter-spacing: .04em; }
.metric.accent .metric-label { color: rgba(255,255,255,.8); }
.metric-value { font-size: 1.5rem; font-weight: 800; }
.charts { align-items: start; }
.bar-chart { display: flex; flex-direction: column; gap: .5rem; margin-top: .8rem; }
.bar-row { display: grid; grid-template-columns: 110px 1fr 34px; gap: .5rem; align-items: center; font-size: .8rem; }
.bar-label { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; color: var(--muted); }
.bar-track { background: var(--surface-soft); border-radius: 6px; height: 14px; overflow: hidden; }
.bar-fill { height: 100%; background: linear-gradient(90deg, #2f9c73, #0d6e4f); border-radius: 6px; }
.bar-value { text-align: right; }
.low-stock-list { list-style: none; padding: 0; margin: .5rem 0 0; }
.low-stock-list li { display: flex; justify-content: space-between; padding: .4rem 0; border-bottom: 1px solid var(--border); font-size: .85rem; }
.low-stock-list strong { color: var(--warn); }
.legend { display: flex; gap: 1rem; font-size: .8rem; color: var(--muted); }
.legend .dot { display: inline-block; width: 9px; height: 9px; border-radius: 50%; margin-right: .35rem; }
.dot.orders { background: #0d6e4f; }
.dot.revenue { background: var(--accent); }
.trend-svg { width: 100%; height: auto; margin-top: .5rem; }
.axis { stroke: var(--border); stroke-width: 1.5; }
.axis-label { fill: var(--muted); font-size: 10px; }
.line { fill: none; stroke-width: 2.5; stroke-linejoin: round; stroke-linecap: round; }
.line.orders { stroke: #0d6e4f; }
.line.revenue { stroke: var(--accent); stroke-dasharray: 5 4; }
.point.orders { fill: #0d6e4f; }
.point.revenue { fill: var(--accent); }

/* ---------- responsive ---------- */
@media (max-width: 960px) {
  .topbar-inner { flex-wrap: wrap; gap: .6rem; }
  .main-nav { order: 3; width: 100%; overflow-x: auto; }
  .user-name { display: none; }
  .console-shell { grid-template-columns: 1fr; }
