 1→package com.webox.security;
 2→
 3→import com.webox.common.ApiException;
 4→import com.webox.common.CurrentUser;
 5→import com.webox.common.ErrorCode;
 6→import com.webox.common.RequestContext;
 7→import jakarta.servlet.http.HttpServletRequest;
 8→import jakarta.servlet.http.HttpServletResponse;
 9→import org.springframework.stereotype.Component;
10→import org.springframework.web.method.HandlerMethod;
11→import org.springframework.web.servlet.HandlerInterceptor;
12→
13→import java.util.Arrays;
14→
15→/** Bearer token verification + role check for every /api/** endpoint except public auth/meta. */
16→@Component
17→public class AuthInterceptor implements HandlerInterceptor {
18→
19→    private final JwtUtil jwt;
20→
21→    public AuthInterceptor(JwtUtil jwt) {
22→        this.jwt = jwt;
23→    }
24→
25→    @Override
26→    public boolean preHandle(HttpServletRequest request, HttpServletResponse response, Object handler) {
27→        if ("OPTIONS".equalsIgnoreCase(request.getMethod())) return true;
28→        String path = request.getRequestURI();
29→        // Public: auth endpoints, static enums, and uploaded/public dish images.
30→        // /api/auth/me is intentionally NOT public.
31→        if (path.startsWith("/api/uploads/") || path.equals("/api/meta")
32→                || path.equals("/api/auth/register") || path.equals("/api/auth/login")
33→                || path.equals("/api/auth/refresh") || path.equals("/api/auth/logout")) {
34→            return true;
35→        }
36→
37→        String header = request.getHeader("Authorization");
38→        if (header == null || !header.startsWith("Bearer ")) {
39→            throw new ApiException(ErrorCode.UNAUTHORIZED, "Please sign in to continue.");
40→        }
41→        JwtUtil.Claims claims = jwt.verify(header.substring(7));
42→        RequestContext.setUser(new CurrentUser(
43→                claims.userId(), claims.email(), claims.name(), claims.role()));
44→
45→        if (handler instanceof HandlerMethod method) {
46→            RequireRole annotation = method.getMethodAnnotation(RequireRole.class);
47→            if (annotation == null) {
48→                annotation = method.getBeanType().getAnnotation(RequireRole.class);
49→            }
50→            if (annotation != null && Arrays.stream(annotation.value())
51→                    .noneMatch(role -> role.equals(claims.role()))) {
52→                throw new ApiException(ErrorCode.FORBIDDEN,
53→                        "This area is only available to administrators.");
54→            }
55→        }
56→        return true;
57→    }
58→}
